CREATE OR REPLACE FUNCTION public.save_screen_visibility(p_actor text,p_scope text,p_value text,p_rows jsonb) RETURNS void LANGUAGE plpgsql SET search_path=public AS $$ DECLARE r jsonb; BEGIN IF p_actor<>'MASTER-ADMIN' THEN RAISE EXCEPTION 'Not authorized'; END IF; FOR r IN SELECT * FROM jsonb_array_elements(p_rows) LOOP IF r->'visible'='null'::jsonb THEN DELETE FROM public."Screen_Visibility_Rules" WHERE screen=r->>'screen' AND scope=p_scope AND value=p_value; ELSE INSERT INTO public."Screen_Visibility_Rules"(screen,scope,value,visible,updated_by) VALUES(r->>'screen',p_scope,p_value,(r->>'visible')::boolean,p_actor) ON CONFLICT(screen,scope,value) DO UPDATE SET visible=EXCLUDED.visible,updated_by=p_actor; END IF; END LOOP; END $$; REVOKE ALL ON FUNCTION public.save_screen_visibility(text,text,text,jsonb) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.save_screen_visibility(text,text,text,jsonb) TO service_role;